static inline bool _nino_ct_streq(const char* a, const char* b) {
    if (!a || !b) return false;
    size_t la = strlen(a), lb = strlen(b);
    if (la != lb || la == 0) return false;
    volatile uint8_t diff = 0;
    for (size_t i = 0; i < la; i++) { diff |= (uint8_t)(a[i] ^ b[i]); }
    return diff == 0;
}
static inline void nino_init_args(int argc, char** argv) {
    nino_argc = argc;
    nino_argv = argv;
#ifdef NINO_HAS_PCC_CERTIFICATE
    if (argc > 1 && (strcmp(argv[1], "--verify-proof") == 0 || strcmp(argv[1], "--proof-info") == 0)) {
        const char* user_hmac_key = getenv("NINO_PCC_HMAC_KEY");
        const char* user_pubkey = getenv("NINO_PCC_ED25519_PUB");
        bool reverify_z3 = false;
        for (int ai = 2; ai < argc; ai++) {
            if (strcmp(argv[ai], "--hmac-key") == 0 && ai + 1 < argc) { user_hmac_key = argv[++ai]; }
            else if (strcmp(argv[ai], "--pubkey") == 0 && ai + 1 < argc) { user_pubkey = argv[++ai]; }
            else if (strcmp(argv[ai], "--reverify-z3") == 0) { reverify_z3 = true; }
        }
        const char* calc_smt_sha = sha256(_NINO_PCC_SMT_SPEC);
        char seal_input[512];
        snprintf(seal_input, sizeof(seal_input), "%s:%s:%d:%s:%s", _NINO_PCC_SRC_SHA, _NINO_PCC_SMT_SHA, _NINO_PCC_THEOREMS, _NINO_PCC_LOGIC, _NINO_PCC_VERDICT);
        const char* calc_seal_sha = sha256(seal_input);
        int actual_checks = 0;
        const char* sp = _NINO_PCC_SMT_SPEC;
        while ((sp = strstr(sp, "(check-sat)")) != NULL) { actual_checks++; sp += 11; }
        bool has_assert = (strstr(_NINO_PCC_SMT_SPEC, "(assert ") != NULL);
        bool no_vacuous = (strstr(_NINO_PCC_SMT_SPEC, "NO_VERIFICATION_OBLIGATIONS") == NULL && strstr(_NINO_PCC_SMT_SPEC, "PCC_UNSUPPORTED_OBLIGATION") == NULL);
        bool bv_consistent = (strstr(_NINO_PCC_LOGIC, "QF_BV") == NULL || strstr(_NINO_PCC_SMT_SPEC, "(_ BitVec 64)") != NULL);
        bool fp_consistent = (strstr(_NINO_PCC_LOGIC, "IEEE754") == NULL || strstr(_NINO_PCC_SMT_SPEC, "Float64") != NULL);
        bool spec_valid = (actual_checks >= 1 && actual_checks == _NINO_PCC_CHECK_CNT && has_assert && no_vacuous && bv_consistent && fp_consistent);
        bool smt_match = _nino_ct_streq(calc_smt_sha, _NINO_PCC_SMT_SHA);
        bool seal_match = _nino_ct_streq(calc_seal_sha, _NINO_PCC_SEAL_SHA);
        bool verdict_ok = (_NINO_PCC_THEOREMS >= 1 && strncmp(_NINO_PCC_VERDICT, "UNSAT Verified", 14) == 0);
        char mac_payload[576];
        snprintf(mac_payload, sizeof(mac_payload), "NINO_PCC_V2:%s:%s:%d:%d:%s:%s", _NINO_PCC_SRC_SHA, _NINO_PCC_SMT_SHA, _NINO_PCC_THEOREMS, _NINO_PCC_CHECK_CNT, _NINO_PCC_LOGIC, _NINO_PCC_VERDICT);
        bool mac_match = false;
        if (_NINO_PCC_KEYED != 0) {
            if (user_hmac_key && user_hmac_key[0] != 0) {
                mac_match = _nino_ct_streq(hmac_sha256(user_hmac_key, mac_payload), _NINO_PCC_MAC_TAG);
            }
        } else {
            char dkey[256];
            if (user_hmac_key && user_hmac_key[0] != 0) { snprintf(dkey, sizeof(dkey), "%s", user_hmac_key); }
            else { snprintf(dkey, sizeof(dkey), "NINO_PCC_DOMAIN_V2:%s", _NINO_PCC_SRC_SHA); }
            mac_match = _nino_ct_streq(hmac_sha256(dkey, mac_payload), _NINO_PCC_MAC_TAG);
        }
        bool ed_match = true;
#ifdef NINO_PCC_ED25519
        ed_match = false;
        if (strlen(_NINO_PCC_ED25519_PUB) == 64 && strlen(_NINO_PCC_ED25519_SIG) == 128) {
            bool pk_pin_ok = true;
            if (user_pubkey && user_pubkey[0] != 0) { pk_pin_ok = _nino_ct_streq(user_pubkey, _NINO_PCC_ED25519_PUB); }
            if (pk_pin_ok) {
                uint8_t ed_pk[32]; uint8_t ed_sig[64];
                for (int i = 0; i < 32; i++) ed_pk[i] = (uint8_t)((_nino_hex_nib(_NINO_PCC_ED25519_PUB[i*2]) << 4) | _nino_hex_nib(_NINO_PCC_ED25519_PUB[i*2+1]));
                for (int i = 0; i < 64; i++) ed_sig[i] = (uint8_t)((_nino_hex_nib(_NINO_PCC_ED25519_SIG[i*2]) << 4) | _nino_hex_nib(_NINO_PCC_ED25519_SIG[i*2+1]));
                ed_match = _nino_ed25519_verify_raw((const uint8_t*)mac_payload, strlen(mac_payload), ed_pk, ed_sig);
            }
        }
#endif
        bool z3_reverify_ok = true;
        if (reverify_z3 && spec_valid && smt_match && seal_match && mac_match && ed_match && verdict_ok) {
            char tmp_smt[64]; char tmp_out[64]; char cmd_buf[1024];
            snprintf(tmp_smt, sizeof(tmp_smt), "_nino_pcc_chk_%llu.smt2", (unsigned long long)clock());
            snprintf(tmp_out, sizeof(tmp_out), "_nino_pcc_chk_%llu.out", (unsigned long long)clock());
            FILE* sf = fopen(tmp_smt, "wb");
            if (sf) { fwrite(_NINO_PCC_SMT_SPEC, 1, strlen(_NINO_PCC_SMT_SPEC), sf); fclose(sf); } else { z3_reverify_ok = false; }
            if (z3_reverify_ok) {
                snprintf(cmd_buf, sizeof(cmd_buf), "z3 -T:15 -t:10000 -smt2 \"%s\" > \"%s\" 2>&1", tmp_smt, tmp_out);
                if (system(cmd_buf) != 0) {
                    int z3_rc = -1;
#ifdef _WIN32
                    snprintf(cmd_buf, sizeof(cmd_buf), "tools\\z3.exe -T:15 -t:10000 -smt2 \"%s\" > \"%s\" 2>&1", tmp_smt, tmp_out);
                    z3_rc = system(cmd_buf);
                    if (z3_rc != 0) {
                        const char* nh = getenv("NINO_HOME");
                        if (nh && nh[0]) {
                            snprintf(cmd_buf, sizeof(cmd_buf), "\"\"%s\\tools\\z3.exe\" -T:15 -t:10000 -smt2 \"%s\" > \"%s\" 2>&1\"", nh, tmp_smt, tmp_out);
                            z3_rc = system(cmd_buf);
                        }
                    }
#else
                    snprintf(cmd_buf, sizeof(cmd_buf), "tools/z3 -T:15 -t:10000 -smt2 \"%s\" > \"%s\" 2>&1", tmp_smt, tmp_out);
                    z3_rc = system(cmd_buf);
                    if (z3_rc != 0) {
                        const char* nh = getenv("NINO_HOME");
                        if (nh && nh[0]) {
                            snprintf(cmd_buf, sizeof(cmd_buf), "\"%s/tools/z3\" -T:15 -t:10000 -smt2 \"%s\" > \"%s\" 2>&1", nh, tmp_smt, tmp_out);
                            z3_rc = system(cmd_buf);
                        }
                    }
#endif
                    (void)z3_rc;
                }
                FILE* rf = fopen(tmp_out, "rb");
                int r_unsat = 0; bool r_sat = false;
                if (rf) { char ln[256]; while (fgets(ln, sizeof(ln), rf)) { if (strncmp(ln, "unsat", 5) == 0) r_unsat++; else if (strncmp(ln, "sat", 3) == 0 || strncmp(ln, "unknown", 7) == 0 || strstr(ln, "error") != NULL) r_sat = true; } fclose(rf); } else { z3_reverify_ok = false; }
                if (r_sat || r_unsat < actual_checks) z3_reverify_ok = false;
            }
            remove(tmp_smt); remove(tmp_out);
        }
        printf("================================================================================\n");
        printf("[Nino Sovereign Proof-Carrying Binary (PCC v1.0)]\n");
#ifdef NINO_PCC_ED25519
        printf("  Binary Integrity : Integrity-Sealed SMT Specification (Ed25519 + HMAC-SHA256 + SHA-256)\n");
#else
        printf("  Binary Integrity : Integrity-Sealed SMT Specification (HMAC-SHA256 + SHA-256)\n");
#endif
        printf("  Source Digest    : %s\n", _NINO_PCC_SRC_SHA);
        printf("  SMT Spec Digest  : %s\n", _NINO_PCC_SMT_SHA);
        printf("  Logic Profile    : %s\n", _NINO_PCC_LOGIC);
#ifdef NINO_PCC_ED25519
        printf("  Auth Scheme      : %s\n", _NINO_PCC_KEYED ? "RFC 8032 Ed25519 + External HMAC-SHA256" : "RFC 8032 Ed25519 Asymmetric + Domain HMAC-SHA256");
#else
        printf("  Auth Scheme      : %s\n", _NINO_PCC_KEYED ? "External Secret Key (RFC 2104 HMAC-SHA256)" : "Domain Seal Key (RFC 2104 HMAC-SHA256)");
#endif
        printf("  CryptographicSeal: %s\n", _NINO_PCC_SEAL_SHA);
        printf("  HMAC-SHA256 Tag  : %s\n", _NINO_PCC_MAC_TAG);
#ifdef NINO_PCC_ED25519
        printf("  Ed25519 PubKey   : %s\n", _NINO_PCC_ED25519_PUB);
        printf("  Ed25519 Sig      : %s\n", _NINO_PCC_ED25519_SIG);
#endif
        printf("  Solver Engine    : Microsoft Z3 SMT Theorem Prover\n");
        printf("  Proof Verdict    : [\033[92m✓ %s\033[0m]\n", _NINO_PCC_VERDICT);
        printf("  Theorems Proven  : %d Active Invariants (%d Z3 Queries)\n", _NINO_PCC_THEOREMS, actual_checks);
        if (!spec_valid || !smt_match || !seal_match || !mac_match || !ed_match || !verdict_ok || !z3_reverify_ok) {
            printf("  Runtime Audit    : [✗ PCC CRYPTOGRAPHIC INTEGRITY CHECK FAILED]\n");
            printf("================================================================================\n");
            exit(1);
        }
#ifdef NINO_PCC_ED25519
        printf("  Runtime Audit    : [✓ Embedded SMT Spec, SHA-256, HMAC-SHA256 & Ed25519 Re-Verified]\n");
#else
        printf("  Runtime Audit    : [✓ Embedded SMT Spec, SHA-256 & HMAC-SHA256 Re-Verified]\n");
#endif
        printf("================================================================================\n");
        exit(0);
    }
#else
    if (argc > 1 && (strcmp(argv[1], "--verify-proof") == 0 || strcmp(argv[1], "--proof-info") == 0)) {
        printf("================================================================================\n");
        printf("[Nino Sovereign Binary]\n");
        printf("  Status: Standalone native executable (Standard Compilation Mode)\n");
        printf("  Notice: To embed an SMT proof certificate, recompile with:\n");
        printf("          ninoc build <file.nino> --proof\n");
        printf("================================================================================\n");
        exit(1);
    }
#endif
}
static inline int64_t nino_get_argc(void) { return (int64_t)nino_argc; }
static inline const char* nino_get_arg(int64_t idx) { if (idx < 0 || idx >= nino_argc || !nino_argv) return ""; return nino_argv[idx]; }
static inline const char* get_env(const char* name) { if (!name) return ""; const char* v = getenv(name); return v ? v : ""; }
static inline const char* nino_get_env(const char* name) { return get_env(name); }
static inline int64_t nino_char_code(const char* s) { if (!s || !s[0]) return 0; return (int64_t)((unsigned char)s[0]); }
static inline void _nino_trace_auto_dump(void);
static inline void nino_require(bool cond, const char* msg) { if (!cond) { fprintf(stderr, "[Nino Precondition Violation] require() failed: %s\n", msg ? msg : ""); _nino_trace_auto_dump(); exit(1); } }
static inline void nino_ensure(bool cond, const char* msg) { if (!cond) { fprintf(stderr, "[Nino Postcondition Violation] ensure() failed: %s\n", msg ? msg : ""); _nino_trace_auto_dump(); exit(1); } }
static inline void nino_panic(const char* msg) { fprintf(stderr, "[Nino Panic] %s\n", msg ? msg : ""); exit(1); }
