static inline bool _nino_ed25519_verify_raw(const uint8_t* m, size_t n, const uint8_t pk[32], const uint8_t sig[64]) { _nino_ed_init(); uint32_t bw = 0; for (int i = 0; i < 32; i++) { int d = (int)sig[32 + i] - (int)_nino_ed_L[i] - (int)bw; bw = (d < 0) ? 1U : 0U; } if (bw == 0) return false; nino_edpt A, R; if (!_nino_ed_decode(&A, pk)) return false; if (!_nino_ed_decode(&R, sig)) return false; uint8_t* tmp = (uint8_t*)malloc(n + 64); if (!tmp) return false; memcpy(tmp, sig, 32); memcpy(tmp + 32, pk, 32); if (n > 0) memcpy(tmp + 64, m, n); uint8_t k_hash[64], k[32]; _nino_sha512_raw(tmp, n + 64, k_hash); free(tmp); _nino_sc_reduce(k, k_hash); nino_edpt lhs, kA, rhs; _nino_ed_mul(&lhs, &_nino_ed_base, sig + 32); _nino_ed_mul(&kA, &A, k); _nino_ed_add(&rhs, &R, &kA); uint8_t lb[32], rb[32]; _nino_ed_encode(lb, &lhs); _nino_ed_encode(rb, &rhs); uint8_t diff = 0; for (int i = 0; i < 32; i++) diff |= (uint8_t)(lb[i] ^ rb[i]); return diff == 0; }
static inline const char* ed25519_keygen_seed(const char* seed_hex) { if (!seed_hex || strlen(seed_hex) < 64) return ""; uint8_t seed[32], pk[32], sk[64]; for (int i = 0; i < 32; i++) seed[i] = (uint8_t)((_nino_hex_nib(seed_hex[i*2]) << 4) | _nino_hex_nib(seed_hex[i*2+1])); _nino_ed25519_from_seed(pk, sk, seed); char* out = (char*)nino_arena_alloc(194); if (!out) return ""; for (int i = 0; i < 32; i++) snprintf(out + i*2, 3, "%02x", (unsigned int)pk[i]); out[64] = ':'; for (int i = 0; i < 64; i++) snprintf(out + 65 + i*2, 3, "%02x", (unsigned int)sk[i]); out[193] = 0; return out; }
