static inline const char* sanitize(const char* s) { if (!s) return ""; size_t l = strlen(s); char* b = (char*)nino_arena_alloc(l * 6 + 1); if (!b) return s; size_t j = 0; for (size_t i = 0; i < l; i++) { if (s[i] == 60) { memcpy(b + j, "&lt;", 4); j += 4; } else if (s[i] == 62) { memcpy(b + j, "&gt;", 4); j += 4; } else if (s[i] == 38) { memcpy(b + j, "&amp;", 5); j += 5; } else if (s[i] == 34) { memcpy(b + j, "&quot;", 6); j += 6; } else if (s[i] == 39) { memcpy(b + j, "&#x27;", 6); j += 6; } else { b[j++] = s[i]; } } b[j] = 0; return b; }
